contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking parameters to drive C
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has enough Ether to deposit
        require(address(this).balance >= depositAmount);

        // record C's on-chain balance before any action
        uint cBalanceBefore = address(c).balance;

        // perform a deposit into C
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record C's on-chain balance immediately after deposit
        uint cBalanceAfterDeposit = address(c).balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record balances after withdraw attempt
        uint cBalanceAfter = address(c).balance;
        uint testerBalanceAfter = address(this).balance;

        // General rule (single assert):
        // 1) withdrawAll never increases C's on-chain balance beyond what it was after the deposit
        // 2) if withdrawAll returned (did not revert) then the test contract's balance did not decrease
        // 3) in all cases C's balance after is <= cBalanceBefore + depositAmount
        assert(
            cBalanceAfter <= cBalanceAfterDeposit
            && (reverted || testerBalanceAfter >= address(this).balance - 0)
            && cBalanceAfter <= cBalanceBefore + depositAmount
        );
    }

    // allow receiving Ether when withdrawAll sends funds
    receive() external payable {}
}

